import json
# 가상 JSON 로그 — 서버마다 따로 남겼지만 traceId 가 같다
logs = """{"svc":"gateway","traceId":"a1","ms":612}
{"svc":"home-bff","traceId":"a1","ms":598}
{"svc":"recommend","traceId":"a1","ms":41}
{"svc":"product","traceId":"a1","ms":540}
{"svc":"coupon","traceId":"a1","ms":22}
{"svc":"gateway","traceId":"b2","ms":75}""".splitlines()
rows = [json.loads(l) for l in logs]
for g in (r for r in rows if r["svc"] == "gateway" and r["ms"] > 300):
    hops = sorted((r for r in rows if r["traceId"] == g["traceId"] and r["svc"] not in ("gateway", "home-bff")),
                  key=lambda r: -r["ms"])
    print(f'느린 요청 {g["traceId"]} {g["ms"]}ms → 가장 오래 걸린 곳: {hops[0]["svc"]} {hops[0]["ms"]}ms')
